import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷一·15","description":"易小帖 - 卷一·15","frontmatter":{"title":"卷一·15","description":"易小帖 - 卷一·15"},"headers":[],"relativePath":"classics/yixiaotie/015.md","filePath":"classics/yixiaotie/015.md"}'),o={name:"classics/yixiaotie/015.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷一·15",tabindex:"-1"},[r("卷一·15 "),e("a",{class:"header-anchor",href:"#卷一·15","aria-label":"Permalink to “卷一·15”"},"​")],-1),e("p",null,"離有飛鳥之象，《說卦》逸義曰：離為飛鳥，以離位正南，值鶉火之次。鶉為朱鳥，《虞書》所雲星鳥是也。若《歸藏》初巽曰「有鳥將來，而垂其翼」，薛貞曰「巽值鶉尾，故稱飛鳥」，此當如小過互巽飛鳥，與明夷之以離為飛鳥不同，蓋巽位東南，正與離近當鶉火之尾，故離巽皆象飛鳥，以木火子母本相通故也。若《說卦》巽為雞，離為雉，八畜之中，獨離巽屬禽翼，亦有取象飛鳥之意。且兩畜木火亦正相通，《素問》以雞為木畜，而實銜火精雉，本午質火文，而月令雉雊而雷發聲，《漢書》陳倉有聲如雷，而野雉皆雊。則夏禽而感春氣，皆木火相通之驗，故知《說卦》逸義雖極精當，然尚有未備。其偶作補苴，非多事也。",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
